draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  // sun
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  // clouds
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + 100 * Math.cos(t + i), H / 2 + 50 * Math.sin(t + i), 20 + 10 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.stroke();
  }
  // tree
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 50);
  ctx.lineTo(W / 2, H - 150 - 50 * Math.sin(t));
  ctx.stroke();
  // leaves
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + 20 * Math.cos(t + i), H - 150 - 50 * Math.sin(t) + 20 * Math.sin(t + i), 10, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}
